[{"order":1,"type":"heading","text":"Tracing, Videos, and Screenshots Configuration in Playwright"},{"order":2,"type":"paragraph","text":"Configuring artifacts like screenshots, videos, and traces in Playwright is essential for debugging failed tests and maintaining robust test suites. This tutorial covers how to set up these diagnostics in your Playwright configuration file."},{"order":3,"type":"subheading","text":"Configuring the Playwright Configuration File"},{"order":4,"type":"paragraph","text":"Playwright uses a central configuration file, typically named playwright.config.ts, where you can define global settings for all your tests under the use object."},{"order":5,"type":"code","text":"import { defineConfig } from '@playwright/test';

export default defineConfig({
  use: {
    screenshot: 'on',
    video: 'retain-on-failure',
    trace: 'on-first-retry',
  },
});"},{"order":6,"type":"subheading","text":"Understanding Screenshot Options"},{"order":7,"type":"paragraph","text":"Screenshots help visually verify the state of the application at specific moments. You can control when screenshots are captured using the following values:"},{"order":8,"type":"bullet_point","text":"'off': Do not capture screenshots."},{"order":9,"type":"bullet_point","text":"'on': Capture screenshots for every test."},{"order":10,"type":"bullet_point","text":"'only-on-failure': Capture screenshots only when a test fails."},{"order":11,"type":"subheading","text":"Understanding Video Recording Options"},{"order":12,"type":"paragraph","text":"Recordings provide a full playback of the test execution, which is extremely helpful for asynchronous UI bugs."},{"order":13,"type":"bullet_point","text":"'off': Do not record videos."},{"order":14,"type":"bullet_point","text":"'on': Record videos for all tests."},{"order":15,"type":"bullet_point","text":"'retain-on-failure': Record videos for all tests, but discard all videos except for failed tests."},{"order":16,"type":"bullet_point","text":"'on-first-retry': Record videos only when retrying a failed test for the first time."},{"order":17,"type":"subheading","text":"Configuring Traces for Deep Debugging"},{"order":18,"type":"paragraph","text":"Playwright traces capture a comprehensive record of test execution, including action snapshots, source code, network requests, and console logs. You can open them using the Playwright Trace Viewer."},{"order":19,"type":"code","text":"// Example setting trace to record on the first retry of a failed test
trace: 'on-first-retry'"},{"order":20,"type":"subheading","text":"Viewing Traces"},{"order":21,"type":"paragraph","text":"Once a trace file (usually a .zip file) is generated, you can inspect it via the command line using the following command:"},{"order":22,"type":"code","text":"npx playwright show-trace path/to/trace.zip"},{"order":23,"type":"paragraph","text":"By appropriately tuning these options, you ensure your CI/CD pipelines remain performant while still collecting enough diagnostic data to resolve flaky or failing tests quickly."}]
